using System;
using System.Linq;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
namespace CampaignDemo.Editor {
 public sealed class MapDetailWindow:EditorWindow {
  MapDetailRegions data;MapDetailRegions.DetailKind kind=MapDetailRegions.DetailKind.RuralMix;int seed=217,selected=-1;float density=1,green=.55f,plotScale=1;Vector2 pageScroll,scroll,start,finish;bool drawing,dragging;int control;
  [MenuItem("Tools/态势地图/框选生成村落与农田")]
  public static void Open(){var window=GetWindow<MapDetailWindow>("区域生成 · 村落农田");window.minSize=new Vector2(330,480);window.Show();}
  void OnEnable(){SceneView.duringSceneGui+=SceneGUI;Undo.undoRedoPerformed+=UndoRedo;Find();}
  void OnDisable(){SceneView.duringSceneGui-=SceneGUI;Undo.undoRedoPerformed-=UndoRedo;if(dragging)GUIUtility.hotControl=0;drawing=dragging=false;}
  void Find(){data=UnityEngine.Object.FindObjectOfType<MapDetailRegions>();}
  void UndoRedo(){if(data==null)return;EditorApplication.delayCall+=()=>{if(data!=null&&!EditorApplication.isPlaying)MapDetailBaker.Bake(data);Repaint();SceneView.RepaintAll();};}
  public static MapDetailRegions Ensure(){var existing=UnityEngine.Object.FindObjectOfType<MapDetailRegions>();if(existing!=null)return existing;var terrain=UnityEngine.Object.FindObjectOfType<FreeMarchMapRuntime>();if(terrain==null)throw new InvalidOperationException("请先打开战场场景");var data=Undo.AddComponent<MapDetailRegions>(terrain.gameObject);data.Resolve();return data;}
  void OnGUI(){
   EditorGUILayout.HelpBox("你决定位置，程序生成细节。选择类型 → 开启框选 → 在Scene场景视图拖框，松开生成。按Esc退出框选。",MessageType.Info);
   if(EditorApplication.isPlaying){EditorGUILayout.HelpBox("请先停止运行，地图细节在编辑时生成并缓存。",MessageType.Warning);return;}
   data=(MapDetailRegions)EditorGUILayout.ObjectField("区域生成器",data,typeof(MapDetailRegions),true);
   if(data==null){if(GUILayout.Button("为当前地图创建生成器"))data=Ensure();return;}data.Resolve();pageScroll=EditorGUILayout.BeginScrollView(pageScroll);
   bool fields=EditorGUILayout.Toggle("显示农田",data.generateFarmland);if(fields!=data.generateFarmland){Undo.RecordObject(data,"切换农田显示");data.generateFarmland=fields;MapDetailBaker.Bake(data);}
   kind=(MapDetailRegions.DetailKind)EditorGUILayout.Popup("框选内容",(int)kind,new[]{"村落（院落与周边田）","农田（带田埂）","混合乡村（村落与农田）"});seed=EditorGUILayout.IntField("新区域种子",seed);density=EditorGUILayout.Slider("密度",density,.2f,2);green=EditorGUILayout.Slider("褐色田比例",green,0,1);plotScale=EditorGUILayout.Slider("田块大小",plotScale,.2f,2);
   using(new EditorGUILayout.HorizontalScope()){if(GUILayout.Button(drawing?"结束框选":"开始框选区域")){drawing=!drawing;dragging=false;if(drawing&&SceneView.lastActiveSceneView!=null){SceneView.lastActiveSceneView.in2DMode=true;SceneView.lastActiveSceneView.Focus();}SceneView.RepaintAll();}if(GUILayout.Button("定位整张地图")){var view=SceneView.lastActiveSceneView;if(view!=null){view.in2DMode=true;var b=data.terrain.definition.bounds;view.Frame(new Bounds(data.terrain.transform.TransformPoint(b.center),new Vector3(b.width,b.height,.1f)),false);}}}
   EditorGUILayout.LabelField("已有区域（可单独编辑、重生成）",EditorStyles.boldLabel);scroll=EditorGUILayout.BeginScrollView(scroll,GUILayout.Height(Mathf.Clamp(data.areas.Count*24,48,144)));
   for(int i=0;i<data.areas.Count;i++){var area=data.areas[i];if(area==null)continue;using(new EditorGUILayout.HorizontalScope()){if(GUILayout.Toggle(selected==i,area.name,"Button"))selected=i;if(GUILayout.Button("×",GUILayout.Width(25))){Undo.RecordObject(data,"删除生成区域");data.areas.RemoveAt(i);selected=-1;MapDetailBaker.Bake(data);GUIUtility.ExitGUI();}}}
   EditorGUILayout.EndScrollView();if(selected>=0&&selected<data.areas.Count){var area=data.areas[selected];EditorGUILayout.Space();EditorGUILayout.LabelField("编辑选中区域",EditorStyles.boldLabel);EditorGUI.BeginChangeCheck();string name=EditorGUILayout.TextField("名称",area.name);Rect rect=EditorGUILayout.RectField("地图坐标范围",area.bounds);int s=EditorGUILayout.IntField("种子",area.seed);int type=EditorGUILayout.Popup("内容",(int)area.kind,new[]{"村落","农田","混合乡村"});float den=EditorGUILayout.Slider("密度",area.density,.2f,2),g=EditorGUILayout.Slider("褐色比例",area.greenFields,0,1),scale=EditorGUILayout.Slider("田块大小",area.plotScale,.2f,2);if(EditorGUI.EndChangeCheck()){Undo.RecordObject(data,"调整区域生成参数");area.name=name;area.bounds=Clip(rect,data.terrain.definition.bounds);area.seed=s;area.kind=(MapDetailRegions.DetailKind)type;area.density=den;area.greenFields=g;area.plotScale=scale;EditorUtility.SetDirty(data);}using(new EditorGUILayout.HorizontalScope()){if(GUILayout.Button("按当前参数重生成"))MapDetailBaker.Bake(data);if(GUILayout.Button("换个随机种子")){Undo.RecordObject(data,"更换区域种子");area.seed=unchecked(area.seed+7919);MapDetailBaker.Bake(data);}}}
   EditorGUILayout.LabelField("生成结果",data.generatedVillages+" 村落 / "+data.generatedBuildings+" 建筑 / "+data.generatedFields+" 田块");
   using(new EditorGUILayout.HorizontalScope()){if(GUILayout.Button("重新生成全部预览"))MapDetailBaker.Bake(data);if(GUILayout.Button("保存地图")){MapDetailBaker.Bake(data);EditorSceneManager.SaveScene(data.gameObject.scene);AssetDatabase.SaveAssets();}}
   EditorGUILayout.HelpBox("这些是制图细节，不新增占点、建筑碰撞或道路加速。生成位置和随机种子保存在场景中，同参数结果一致；Ctrl+Z撤销区域编辑。",MessageType.None);EditorGUILayout.EndScrollView();
  }
  public static Rect Clip(Rect rect,Rect map){float x0=Mathf.Clamp(Mathf.Min(rect.xMin,rect.xMax),map.xMin,map.xMax),x1=Mathf.Clamp(Mathf.Max(rect.xMin,rect.xMax),map.xMin,map.xMax),y0=Mathf.Clamp(Mathf.Min(rect.yMin,rect.yMax),map.yMin,map.yMax),y1=Mathf.Clamp(Mathf.Max(rect.yMin,rect.yMax),map.yMin,map.yMax);return Rect.MinMaxRect(x0,y0,x1,y1);}
  public static void AddArea(MapDetailRegions data,Rect bounds,MapDetailRegions.DetailKind kind,int seed,float density,float green,float scale){data.Resolve();var clipped=Clip(bounds,data.terrain.definition.bounds);if(clipped.width<.3f||clipped.height<.3f)throw new InvalidOperationException("区域太小，请框选至少300米宽和高");Undo.RecordObject(data,"框选生成区域");data.areas.Add(new MapDetailRegions.Area{name=(kind==MapDetailRegions.DetailKind.Village?"村落":kind==MapDetailRegions.DetailKind.Farmland?"农田":"混合乡村")+" "+(data.areas.Count+1),bounds=clipped,kind=kind,seed=seed,density=density,greenFields=green,plotScale=scale});MapDetailBaker.Bake(data);}
  bool Point(Vector2 screen,out Vector2 p){var ray=HandleUtility.GUIPointToWorldRay(screen);var plane=new Plane(data.terrain.transform.forward,data.terrain.transform.position);float distance;if(!plane.Raycast(ray,out distance)){p=Vector2.zero;return false;}p=data.terrain.transform.InverseTransformPoint(ray.GetPoint(distance));return true;}
  void Outline(Rect rect,Color color,string label){var t=data.terrain.transform;var points=new[]{t.TransformPoint(new Vector3(rect.xMin,rect.yMin)),t.TransformPoint(new Vector3(rect.xMax,rect.yMin)),t.TransformPoint(new Vector3(rect.xMax,rect.yMax)),t.TransformPoint(new Vector3(rect.xMin,rect.yMax))};Handles.DrawSolidRectangleWithOutline(points,new Color(color.r,color.g,color.b,.06f),color);Handles.Label(points[3],label);}
  void SceneGUI(SceneView view){if(data==null||EditorApplication.isPlaying)return;data.Resolve();if(data.terrain==null)return;for(int i=0;i<data.areas.Count;i++)if(data.areas[i]!=null)Outline(data.areas[i].bounds,i==selected?Color.yellow:new Color(.35f,.65f,.5f,.6f),data.areas[i].name);if(!drawing)return;var e=Event.current;control=GUIUtility.GetControlID(FocusType.Passive);if(e.type==EventType.Layout)HandleUtility.AddDefaultControl(control);if(e.type==EventType.KeyDown&&e.keyCode==KeyCode.Escape){dragging=drawing=false;GUIUtility.hotControl=0;e.Use();Repaint();return;}Vector2 point;if(!Point(e.mousePosition,out point))return;
   if(e.type==EventType.MouseDown&&e.button==0&&!e.alt){start=finish=point;dragging=true;GUIUtility.hotControl=control;e.Use();}else if(e.type==EventType.MouseDrag&&dragging){finish=point;e.Use();view.Repaint();}else if(e.type==EventType.MouseUp&&e.button==0&&dragging){finish=point;dragging=false;GUIUtility.hotControl=0;var rect=Clip(Rect.MinMaxRect(Mathf.Min(start.x,finish.x),Mathf.Min(start.y,finish.y),Mathf.Max(start.x,finish.x),Mathf.Max(start.y,finish.y)),data.terrain.definition.bounds);try{AddArea(data,rect,kind,seed,density,green,plotScale);selected=data.areas.Count-1;seed=unchecked(seed+1);}catch(Exception error){ShowNotification(new GUIContent(error.Message));}e.Use();Repaint();view.Repaint();}if(dragging)Outline(Rect.MinMaxRect(Mathf.Min(start.x,finish.x),Mathf.Min(start.y,finish.y),Mathf.Max(start.x,finish.x),Mathf.Max(start.y,finish.y)),Color.yellow,"松开生成；Esc取消");}
 }
}
